try { $report = reportData($from, $to); }
catch (Throwable $ex) { http_response_code(503); error_log('[soa] report unavailable'); $error = 'Dane statystyczne są chwilowo niedostępne. Nie zastępujemy ich danymi demonstracyjnymi. Kalendarz działa niezależnie.'; }
pageStart('Statystyki e-kalendarza', 'stats'); ?>
<main id="main" class="stats-main"><div class="hero stats-hero"><img class="title-sprig" src="/assets/decor/sprig-title.webp" alt="" width="160" height="55"><h1>Statystyki e-kalendarza</h1><img class="gold-rule" src="/assets/decor/flourish.svg" alt="" width="270" height="20"><p>Podsumowanie kampanii · grudzień 2026</p></div>
