<?php if ($report): ?>
<div class="kpi-grid"><article class="paper-panel"><p>Odsłony strony</p><strong><?= number_format($report['views'], 0, ',', ' ') ?></strong><span>W wybranym okresie</span></article><article class="paper-panel"><p>Zdarzenia otwarcia</p><strong><?= number_format($report['opens'], 0, ',', ' ') ?></strong><span>W tym ponowne odkrycia</span></article><article class="paper-panel"><p>Okienka z otwarciami</p><strong><?= count(array_filter($report['windows'])) ?> <small>/ 24</small></strong><span>Co najmniej jedno zdarzenie</span></article><article class="paper-panel"><p>Pomiar osób</p><strong class="text-kpi">Nie prowadzimy</strong><span>Zliczamy zdarzenia, nie osoby</span></article></div>
