<?php $max = max(1, ...array_column($report['daily'], 'opens')); for ($i=0;$i<=4;$i++): $y=210-$i*45; ?><line class="chart-gridline" x1="42" x2="630" y1="<?= $y ?>" y2="<?= $y ?>"/><text x="34" y="<?= $y+4 ?>" text-anchor="end" class="chart-label"><?= round($max*$i/4) ?></text><?php endfor; ?>
<?php $width = 580/count($report['daily']); foreach($report['daily'] as $i=>$row): $h=180*$row['opens']/$max; ?><rect class="chart-bar" x="<?= 46+$i*$width ?>" y="<?= 210-$h ?>" width="<?= max(2,$width-5) ?>" height="<?= $h ?>" rx="3"/><text class="chart-label" text-anchor="middle" x="<?= 46+$i*$width+($width-5)/2 ?>" y="230"><?= (int)substr($row['date'],-2) ?></text><?php endforeach; ?></svg>
<details><summary>Pokaż dane wykresu w tabeli</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Dane dzienne"><table><caption>Zdarzenia według daty</caption><thead><tr><th scope="col">Data</th><th scope="col">Odsłony</th><th scope="col">Otwarcia</th></tr></thead><tbody><?php foreach($report['daily'] as $row): ?><tr><th scope="row"><?= e($row['date']) ?></th><td><?= $row['page_views'] ?></td><td><?= $row['opens'] ?></td></tr><?php endforeach; ?></tbody></table></div></details></section>
<section class="paper-panel"><h2>Otwarcia poszczególnych okienek</h2><p>Zdarzenia z wybranego okresu, według numeru okienka.</p><dl class="window-stats"><?php foreach($report['windows'] as $day=>$count): ?><div class="<?= $day===24 ? 'last' : '' ?>"><dt><?= $day ?> grudnia</dt><dd><?= number_format($count,0,',',' ') ?></dd></div><?php endforeach; ?></dl></section></div>
<section class="paper-panel report-export"><div><h2>Raport z wybranego okresu</h2><p><?= e($from) ?> – <?= e($to) ?> · wygenerowano <?= e((new DateTimeImmutable())->format('d.m.Y H:i')) ?></p></div><div class="export-actions"><button class="button" id="print-report" type="button">Drukuj / zapisz PDF</button><a class="button secondary" href="/statystyki/export.php?<?= e(http_build_query(['from'=>$from,'to'=>$to])) ?>">Pobierz CSV</a></div></section>
<section class="methodology"><h2>Jak czytać te liczby?</h2><p>Odsłona to wejście lub odświeżenie strony. Otwarcie to wyświetlenie zadania, również ponowne — nie oznacza wykonania ćwiczenia. Nie identyfikujemy unikalnych osób ani przeglądarek.</p><p>W trybie rzeczywistym pomiar obejmuje tylko zdarzenia po dobrowolnej zgodzie. Brak zgody, blokery, brak sieci i automatyczny ruch wpływają na wyniki. Lokalna historia otwarć jest niezależna od raportu.</p><p><?= $config['analytics_enabled'] ? 'Pomiar skonfigurowany jako aktywny.' : 'Zbieranie danych jest obecnie wyłączone.' ?></p></section>
<?php endif; ?></main><script src="/assets/js/statistics.js" defer></script><?php pageEnd(); ?>
